mapper.select:
SELECT id, alert_type, severity, payment_id, order_id, message
FROM payment_alert_log
WHERE status IN ('PENDING', 'FAILED')
  AND id > #{lastId}
ORDER BY id ASC
LIMIT #{chunkSize}

mapper.update:
UPDATE payment_alert_log
SET status = 'FAILED', retry_count = retry_count + 1, updated_at = NOW(6)
WHERE id = #{id}
